 // v0.1.8 export is read-only with respect to annotation data and source documents.
 safeExportName(raw){
  return String(raw||'').replace(/\.md$/i,'').replace(/[\\/:*?"<>|\x00-\x1f\x7f]/g,' ').replace(/[. ]+$/g,'').trim().slice(0,115);
 }
